import mq3.game.rankings as r
function dump(label,state) value=label+"=";if len(state.reports)>0 then for i=0 to len(state.reports)-1 if i>0 then value=value+"|" end if;value=value+str(state.reports[i].key)+":"+str(state.reports[i].value) end for end if;print(value);state.reports=[];return void end function
function main(args) s=r.create(3);r.G_RankFireWeapon(s,1,r.WP_ROCKET_LAUNCHER);dump("fire",s);r.G_RankFireWeapon(s,1,r.WP_GAUNTLET);dump("gauntlet",s);r.G_RankPickupHealth(s,2,100);dump("health",s);r.G_RankPickupArmor(s,2,50);dump("armor",s);r.G_RankPickupPowerup(s,0,r.PW_REDFLAG);dump("flag",s);r.G_RankPickupPowerup(s,0,r.PW_REGEN);dump("regen",s);r.G_RankPickupHoldable(s,0,r.HI_MEDKIT);r.G_RankUseHoldable(s,0,r.HI_MEDKIT);dump("holdable",s);r.G_RankReward(s,0,r.EF_AWARD_IMPRESSIVE);r.G_RankCapture(s,0);dump("reward",s);r.G_RankUserTeamName(s,0,"Red");print("str=0,-1,"+str(r.QGR_KEY_TEAM_NAME)+",Red");return 0 end function
